CREATE TABLE "User" ("id" UUID NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"name" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Session" ("id" UUID NOT NULL,"tokenHash" TEXT NOT NULL,"userId" UUID NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Session_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Business" ("id" UUID NOT NULL,"name" TEXT NOT NULL,"slug" TEXT NOT NULL,"color" TEXT NOT NULL DEFAULT '#64748b',"active" BOOLEAN NOT NULL DEFAULT true,CONSTRAINT "Business_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CatalogItem" ("id" UUID NOT NULL,"publicCode" TEXT NOT NULL,"title" TEXT NOT NULL,"slug" TEXT,"description" TEXT NOT NULL DEFAULT '',"summary" TEXT NOT NULL DEFAULT '',"typeId" UUID,"categoryId" UUID,"statusId" UUID,"createdById" UUID NOT NULL,"favorite" BOOLEAN NOT NULL DEFAULT false,"inInbox" BOOLEAN NOT NULL DEFAULT false,"archivedAt" TIMESTAMP(3),"lastOpenedAt" TIMESTAMP(3),"openCount" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "CatalogItem_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ItemBusiness" ("itemId" UUID NOT NULL,"businessId" UUID NOT NULL,CONSTRAINT "ItemBusiness_pkey" PRIMARY KEY ("itemId","businessId"));
CREATE TABLE "Block" ("id" UUID NOT NULL,"itemId" UUID NOT NULL,"type" TEXT NOT NULL,"position" INTEGER NOT NULL,"content" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Block_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Category" ("id" UUID NOT NULL,"name" TEXT NOT NULL,"description" TEXT NOT NULL DEFAULT '',"archivedAt" TIMESTAMP(3),CONSTRAINT "Category_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Tag" ("id" UUID NOT NULL,"name" TEXT NOT NULL,CONSTRAINT "Tag_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ItemTag" ("itemId" UUID NOT NULL,"tagId" UUID NOT NULL,CONSTRAINT "ItemTag_pkey" PRIMARY KEY ("itemId","tagId"));
CREATE TABLE "ItemType" ("id" UUID NOT NULL,"name" TEXT NOT NULL,"icon" TEXT NOT NULL DEFAULT 'file',CONSTRAINT "ItemType_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Status" ("id" UUID NOT NULL,"name" TEXT NOT NULL,"color" TEXT NOT NULL DEFAULT '#64748b',"order" INTEGER NOT NULL,CONSTRAINT "Status_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Asset" ("id" UUID NOT NULL,"itemId" UUID NOT NULL,"blockId" UUID,"storageType" TEXT NOT NULL,"fileName" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"size" INTEGER NOT NULL,"path" TEXT NOT NULL,"thumbnail" TEXT,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Asset_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ExternalLink" ("id" UUID NOT NULL,"itemId" UUID NOT NULL,"blockId" UUID,"url" TEXT NOT NULL,"title" TEXT NOT NULL DEFAULT '',"previewMetadata" JSONB,CONSTRAINT "ExternalLink_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Template" ("id" UUID NOT NULL,"name" TEXT NOT NULL,"description" TEXT NOT NULL DEFAULT '',"businessId" UUID,"typeId" UUID,"structure" JSONB NOT NULL,"uses" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Template_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ItemRelation" ("id" UUID NOT NULL,"sourceItemId" UUID NOT NULL,"targetItemId" UUID NOT NULL,"relationType" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ItemRelation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ItemVersion" ("id" UUID NOT NULL,"itemId" UUID NOT NULL,"version" INTEGER NOT NULL,"summary" TEXT NOT NULL DEFAULT '',"snapshot" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ItemVersion_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Embedding" ("id" UUID NOT NULL,"itemId" UUID NOT NULL,"sourceType" TEXT NOT NULL,"sourceId" TEXT,"textChunk" TEXT NOT NULL,"vector" JSONB,"metadata" JSONB,CONSTRAINT "Embedding_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SearchHistory" ("id" UUID NOT NULL,"userId" UUID NOT NULL,"query" TEXT NOT NULL,"results" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SearchHistory_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Activity" ("id" UUID NOT NULL,"userId" UUID NOT NULL,"itemId" UUID,"action" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Activity_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE UNIQUE INDEX "Session_tokenHash_key" ON "Session"("tokenHash"); CREATE INDEX "Session_userId_expiresAt_idx" ON "Session"("userId","expiresAt");
CREATE UNIQUE INDEX "Business_name_key" ON "Business"("name"); CREATE UNIQUE INDEX "Business_slug_key" ON "Business"("slug");
CREATE UNIQUE INDEX "CatalogItem_publicCode_key" ON "CatalogItem"("publicCode"); CREATE INDEX "CatalogItem_updatedAt_idx" ON "CatalogItem"("updatedAt"); CREATE INDEX "CatalogItem_title_idx" ON "CatalogItem"("title"); CREATE INDEX "CatalogItem_inInbox_archivedAt_idx" ON "CatalogItem"("inInbox","archivedAt");
CREATE UNIQUE INDEX "Block_itemId_position_key" ON "Block"("itemId","position"); CREATE UNIQUE INDEX "Category_name_key" ON "Category"("name"); CREATE UNIQUE INDEX "Tag_name_key" ON "Tag"("name"); CREATE UNIQUE INDEX "ItemType_name_key" ON "ItemType"("name"); CREATE UNIQUE INDEX "Status_name_key" ON "Status"("name"); CREATE UNIQUE INDEX "Template_name_key" ON "Template"("name"); CREATE UNIQUE INDEX "ItemRelation_sourceItemId_targetItemId_relationType_key" ON "ItemRelation"("sourceItemId","targetItemId","relationType"); CREATE UNIQUE INDEX "ItemVersion_itemId_version_key" ON "ItemVersion"("itemId","version"); CREATE INDEX "Embedding_itemId_idx" ON "Embedding"("itemId"); CREATE INDEX "Activity_userId_createdAt_idx" ON "Activity"("userId","createdAt");
ALTER TABLE "Session" ADD CONSTRAINT "Session_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
