ALTER TABLE "Template" ADD CONSTRAINT "Template_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Template" ADD CONSTRAINT "Template_typeId_fkey" FOREIGN KEY ("typeId") REFERENCES "ItemType"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "ItemRelation" ADD CONSTRAINT "ItemRelation_sourceItemId_fkey" FOREIGN KEY ("sourceItemId") REFERENCES "CatalogItem"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ItemRelation" ADD CONSTRAINT "ItemRelation_targetItemId_fkey" FOREIGN KEY ("targetItemId") REFERENCES "CatalogItem"("id") ON DELETE CASCADE ON UPDATE CASCADE;
